<template>
  <div class="traffic-world">
    <svg viewBox="0 0 620 310" role="group" aria-label="World map with approximate country locations">
      <circle v-for="(dot,i) in dots" :key="i" :cx="dot[0]" :cy="dot[1]" r="1.55" class="land-dot"/>
      <g v-for="pin in pins" :key="pin.country" :class="['world-pin',{selected:(hovered||selected)===pin.country}]" role="button" tabindex="0" :aria-pressed="selected===pin.country" :aria-label="`${countryName(pin.country)}, ${pin.count} sessions`" @click="$emit('select',pin.country)" @keydown.enter="$emit('select',pin.country)" @keydown.space.prevent="$emit('select',pin.country)" @focus="hovered=pin.country" @blur="hovered=''" @pointerenter="hovered=pin.country" @pointerleave="hovered=''">
        <circle :cx="pin.x" :cy="pin.y" r="15" class="pin-hit"/><circle :cx="pin.x" :cy="pin.y" r="7" class="pin-halo"/><circle :cx="pin.x" :cy="pin.y" r="3" class="pin-dot"/>
        <title>{{ countryName(pin.country) }} · {{ pin.count }} sessions</title>
      </g>
    </svg>
    <span class="map-caption">{{ hovered ? countryName(hovered) : 'Countries and regions' }}</span>
  </div>
</template>
<script setup>
/* global defineProps, defineEmits */
import {ref,computed} from 'vue';
import {geoNaturalEarth1} from 'd3-geo';
import dots from '../../data/trafficMapDots.json';
import {countryName} from '../../utils/visitorContextLabel';
defineEmits(['select']);
const props=defineProps({countries:{type:Array,default:()=>[]},selected:{type:String,default:''}}),hovered=ref('');
// Country centres are schematic markers, never visitor coordinates.
const centres={US:[-98,39],CA:[-106,57],MX:[-102,23],BR:[-51,-10],AR:[-64,-35],CL:[-71,-31],CO:[-74,4],GB:[-2,54],IE:[-8,53],FR:[2,47],DE:[10,51],ES:[-4,40],PT:[-8,39],IT:[12,43],NL:[5,52],BE:[4,51],CH:[8,47],AT:[14,48],SE:[16,63],NO:[9,63],FI:[26,64],DK:[10,56],PL:[19,52],UA:[32,49],RU:[90,60],TR:[35,39],IL:[35,31],SA:[45,24],AE:[54,24],IN:[79,22],PK:[69,30],BD:[90,24],CN:[104,35],HK:[114,22],TW:[121,24],JP:[138,37],KR:[128,37],SG:[104,1],MY:[102,4],TH:[101,16],VN:[106,16],ID:[118,-3],PH:[122,13],AU:[134,-25],NZ:[173,-41],ZA:[25,-29],EG:[30,27],NG:[8,9],KE:[38,1]};
const projection=geoNaturalEarth1().scale(102.10169413889041).translate([310,152.77151953573136]);
const pins=computed(()=>props.countries.filter(row=>centres[row.country]).map(row=>{const[x,y]=projection(centres[row.country]);return{...row,x,y};}));
</script>
<style scoped>
.traffic-world{position:relative;width:100%}.traffic-world svg{width:100%;display:block}.land-dot{fill:var(--traffic-ink);opacity:.15}.world-pin{cursor:pointer;outline:none}.pin-hit{fill:transparent}.pin-halo{fill:var(--traffic-accent);opacity:.12;transition:opacity 160ms}.pin-dot{fill:var(--traffic-accent)}.selected .pin-halo,.world-pin:focus-visible .pin-halo{opacity:.4}.map-caption{position:absolute;bottom:0;left:0;font:.67rem var(--traffic-font);letter-spacing:.06em;color:var(--traffic-muted)}
</style>
